"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def intersection(A, B):
    result = []
    i = 0
    j = 0
    while ((i < len(A)) and (j < len(B))):
        if (A[i] == B[j]):
            result.append(A[i])
            i = (i + 1)
            j = (j + 1)
        elif (A[i] < B[j]):
            i = (i + 1)
        else:
            j = (j + 1)
    return result
